export function getHistoricalSeasonStats(season: string): SeasonStatsPayload {
  const data = HISTORICAL_SEASON_STATS[season];
  if (data) {
    return data;
  }
  // Default fallback to 2024-25 if unknown historical season requested
  return {
    ...HISTORICAL_SEASON_STATS['2024-25'],
    season,
  };
}
